// The app's typography.
// Originally generated by Bloxks; now maintained by hand (Bloxks is no longer used),
// so the fonts are BUNDLED in `assets/fonts/` instead of being downloaded from
// bloxks.app at start-up. iOS, Android and web load the same files.
//
// HOW TO USE (mandatory):
//   import { FONTS, useAppFonts } from './zzz/fonts'
//   <Text style={[styles.title, FONTS.display.bold]}>Hello</Text>
//
// ⚠️ CRITICAL: React Native IGNORES `fontWeight` once a custom font is loaded.
// `{ fontWeight: '600' }` renders REGULAR. To get any weight you MUST spread the
// matching entry below. Never write `fontFamily` or `fontWeight` by hand.
//
// Families (all SIL Open Font License, from Google Fonts):
//   display → Fraunces (warm, editorial serif — titles and hero numbers)
//   text    → Plus Jakarta Sans (body, labels, buttons)
//   mono    → JetBrains Mono (figures in tables, timers, counters)
import { type TextStyle } from 'react-native'
import { useFonts } from 'expo-font'
import { Ionicons } from '@expo/vector-icons'

export const FONT_PACK_ID = "primal-earth"
/** true when at least one platform loads font files, so `fontWeight` alone is not enough. */
export const FONT_CUSTOM = true

type FontSlots = { regular: TextStyle; semibold: TextStyle; bold: TextStyle }
type FontStyles = { display: FontSlots; text: FontSlots; mono: FontSlots }

/**
 * Font files to register. The KEY is the family name used by `fontFamily`.
 */
export const FONT_SOURCES = {
  "AppDisplay-Regular": require('../assets/fonts/Fraunces_400Regular.ttf'),
  "AppDisplay-SemiBold": require('../assets/fonts/Fraunces_600SemiBold.ttf'),
  "AppDisplay-Bold": require('../assets/fonts/Fraunces_700Bold.ttf'),
  "AppText-Regular": require('../assets/fonts/PlusJakartaSans_400Regular.ttf'),
  "AppText-SemiBold": require('../assets/fonts/PlusJakartaSans_600SemiBold.ttf'),
  "AppText-Bold": require('../assets/fonts/PlusJakartaSans_700Bold.ttf'),
  "AppMono-Regular": require('../assets/fonts/JetBrainsMono_400Regular.ttf'),
  "AppMono-SemiBold": require('../assets/fonts/JetBrainsMono_600SemiBold.ttf'),
  "AppMono-Bold": require('../assets/fonts/JetBrainsMono_700Bold.ttf'),
}

/**
 * Ready-to-spread text styles. Build hierarchy with fontSize + these entries,
 * never with `fontWeight`.
 *   display → titles and hero numbers
 *   text    → body, labels, buttons
 *   mono    → figures in tables, timers, counters
 */
export const FONTS: FontStyles = {
  display: {
    regular: { fontFamily: "AppDisplay-Regular" },
    semibold: { fontFamily: "AppDisplay-SemiBold" },
    bold: { fontFamily: "AppDisplay-Bold" },
  },
  text: {
    regular: { fontFamily: "AppText-Regular" },
    semibold: { fontFamily: "AppText-SemiBold" },
    bold: { fontFamily: "AppText-Bold" },
  },
  mono: {
    regular: { fontFamily: "AppMono-Regular" },
    semibold: { fontFamily: "AppMono-SemiBold" },
    bold: { fontFamily: "AppMono-Bold" },
  },
}

/**
 * Loads the fonts (and the Ionicons icon font used on Android / web). Call it
 * ONCE at the root of `App` and hold the first render until it returns true.
 * Returns true on error too: a font that fails to load must never leave the
 * user stuck on a blank screen.
 */
export function useAppFonts(): boolean {
  const [loaded, error] = useFonts({ ...Ionicons.font, ...FONT_SOURCES })
  return loaded || error != null
}
